function plan(api) {
  api.terrain('plain', { amplitude: 1.4, roughness: 0.28, seed: api.seed });

  const circle = (x, z, r) => ({ kind: 'circle', center: [x, z], radius: r });
  const district = {
    kind: 'polygon',
    points: [[-46, -46], [46, -46], [46, 46], [-46, 46]]
  };
  api.surface({ id: 'urban-ground', surface: 'paving', material: 'weathered gray concrete', region: district, intensity: 0.96 });

  const candidates = [-3, 0, 3].map(x => {
    const samples = [-40, -20, 0, 20, 40].map(z => api.environmentSample([x, z]));
    return {
      x: x,
      relief: Math.max.apply(null, samples.map(s => s.height)) - Math.min.apply(null, samples.map(s => s.height))
    };
  });
  candidates.sort((a, b) => a.relief - b.relief);
  const spine = candidates[0].x;

  api.requireAsset({
    key: 'concrete',
    name: '握手楼',
    role: 'structure',
    dimensions: [8, 13.5, 7],
    prompt: 'One standalone dense Chinese urban village residential building, five cramped stories, flat roof, aged pale gray concrete and patchy ceramic tile cladding, dark aluminum windows, projecting barred window cages, numerous wall air conditioners, tangled facade conduits, small balconies with colorful laundry, rooftop water tank within the footprint. Ground floor metal entrance and narrow convenience shop with Chinese signs facing Z+. No surrounding ground or neighboring buildings. Y+ up, Z+ front entrance, X+ right.'
  });
  api.requireAsset({
    key: 'tile',
    name: '瓷砖楼',
    role: 'structure',
    dimensions: [8, 11.5, 7],
    prompt: 'One standalone four story Chinese urban village apartment building, faded cream and green small ceramic tiles, flat parapet roof, irregular enclosed balconies, steel security grilles, external air conditioning units, laundry, rain stains, exposed drainpipes, ground floor repair shop with partly open rolling shutter and Chinese lettering facing Z+. Roof clutter contained within footprint. Y+ up, Z+ front entrance, X+ right.'
  });
  api.requireAsset({
    key: 'brick',
    name: '加建楼',
    role: 'structure',
    dimensions: [8, 14.5, 7],
    prompt: 'One standalone narrow Chinese urban village rental apartment block, five stories of weathered gray plaster with exposed red brick upper extension, flat roof, mismatched windows, steel window cages, compact water tanks and satellite dish, small laundry balconies, ground floor noodle shop with red Chinese sign and short fabric awning facing Z+. All details contained in footprint. Y+ up, Z+ front entrance, X+ right.'
  });
  api.requireAsset({
    key: 'stall',
    name: '菜摊',
    role: 'environment',
    dimensions: [3, 2.5, 2],
    prompt: 'One standalone Chinese neighborhood vegetable market stall, faded striped fabric canopy on slender steel frame, wooden crates full of green vegetables, handwritten Chinese price cards, low counter and plastic bags. Weathered everyday appearance. Y+ up, Z+ customer side, X+ right.'
  });
  api.requireAsset({
    key: 'scooter',
    name: '电动车',
    role: 'environment',
    dimensions: [0.7, 1.2, 1.7],
    prompt: 'One standalone well used Chinese electric scooter with front basket, padded seat, mirrors and modest rear storage box, parked upright on its kickstand. Y+ up, Z+ front, X+ right.'
  });
  api.requireAsset({
    key: 'tree',
    name: '榕树',
    role: 'environment',
    dimensions: [7, 8, 7],
    prompt: 'One standalone mature subtropical banyan street tree, irregular leafy canopy, branching trunk and subtle aerial roots, compact urban growth form. No planter or ground. Y+ up, Z+ front, X+ right.'
  });
  api.requireAsset({
    key: 'pole',
    name: '线杆',
    role: 'environment',
    dimensions: [0.6, 7, 0.6],
    prompt: 'One standalone weathered concrete urban utility pole with small junction boxes, ceramic insulators, short crossarm and a simple downward streetlight, worn paper notices near its base. No long external wires. Y+ up, Z+ front, X+ right.'
  });
  api.requireAsset({
    key: 'wire',
    name: '电线',
    role: 'environment',
    dimensions: [0.12, 0.3, 8],
    prompt: 'One standalone bundled set of three thin dark overhead utility cables, shallow sag, spanning along local Z with endpoints at equal height, no poles. Y+ up, Z+ length direction, X+ right.'
  });

  function road(id, points, width) {
    for (let i = 1; i < points.length; i++) {
      const a = api.environmentSample(points[i - 1]);
      const b = api.environmentSample(points[i]);
      api.rampTerrain({
        start: points[i - 1], end: points[i], width: width + 0.6,
        startHeight: a.height, endHeight: b.height, softness: 0.35, strength: 0.85
      });
    }
    api.route({ id: id, points: points, width: width, curve: 'polyline', surface: 'paving', material: 'patched concrete with dark drainage edges' });
  }

  road('main-lane', [[spine, -46], [spine, -35], [spine, -11], [spine, 11], [spine, 35], [spine, 46]], 4.8);
  [-35, -11, 11, 35].forEach((z, i) => road('cross-lane-' + i, [[-45, z], [spine, z], [45, z]], i === 1 ? 4.2 : 3.2));
  [-44.5, -24, 24, 44.5].forEach((x, i) => road('side-alley-' + i, [[x, -35], [x, -11], [x, 11], [x, 35]], 1.5));

  const xs = [-39, -29, -19, -9, 9, 19, 29, 39];
  const rows = [
    { z: -27, street: -35 }, { z: -18, street: -11 },
    { z: -5, street: -11 }, { z: 3, street: 11 },
    { z: 18, street: 11 }, { z: 27, street: 35 }
  ];
  const types = ['concrete', 'tile', 'brick'];
  const heights = { concrete: 13.5, tile: 11.5, brick: 14.5 };
  const occupied = [];

  for (let r = 0; r < rows.length; r++) {
    for (let c = 0; c < xs.length; c++) {
      if (r === 4 && (c === 5 || c === 6)) continue;
      const x = xs[c];
      const z = rows[r].z;
      const near = api.environmentSample([x, z]);
      const corners = [[x - 4, z - 3.5], [x + 4, z - 3.5], [x - 4, z + 3.5], [x + 4, z + 3.5]];
      const levels = corners.map(p => api.environmentSample(p).height);
      const h = Math.max(near.height, levels.reduce((a, b) => a + b, 0) / levels.length);
      api.sculptTerrain({ mode: 'flatten', point: [x, z], radius: 5.3, strength: 0.95, targetHeight: h });
      const grounded = api.environmentSample([x, z]);
      const toward = rows[r].street > z ? 1 : -1;
      const entry = [x, z + toward * 3.6];
      const street = [x, rows[r].street];
      const entryHeight = api.environmentSample(entry).height;
      const streetHeight = api.environmentSample(street).height;
      api.rampTerrain({
        start: entry, end: street, width: 1.6,
        startHeight: entryHeight, endHeight: streetHeight, softness: 0.3, strength: 1
      });
      api.route({ id: 'door-' + r + '-' + c, points: [entry, street], width: 1.25, surface: 'paving', material: 'worn concrete' });
      const key = types[(c + r * 2) % types.length];
      const building = api.place({
        assetId: api.asset(key), position: [x, grounded.height, z],
        rotationY: toward > 0 ? 0 : Math.PI,
        dimensions: [8, heights[key], 7], role: 'structure'
      });
      api.foundation({
        under: [building], shape: 'rounded-rectangle', width: 8.2, depth: 7.2,
        top: 'level', maxThickness: 1.2, material: 'stained concrete'
      });
      occupied.push([x, z]);

      if ((r + c) % 2 === 0) {
        api.place({
          assetId: api.asset('scooter'),
          position: [x + 2.5, z + toward * 4.6],
          rotationY: Math.PI / 2 + (c % 3) * 0.15,
          role: 'environment'
        });
      }
    }
  }

  api.surface({ id: 'market-court', surface: 'paving', material: 'old irregular concrete slabs', region: { kind: 'polygon', points: [[14.5, 13], [34, 13], [34, 22], [14.5, 22]] }, intensity: 1 });
  road('market-access', [[24, 11], [24, 17], [32, 17]], 2.4);
  for (let i = 0; i < 4; i++) {
    api.place({ assetId: api.asset('stall'), position: [16.5 + i * 4.2, 21], rotationY: Math.PI, role: 'environment' });
  }
  api.place({ assetId: api.asset('tree'), position: [32, 15.5], role: 'environment' });
  api.foundation({ position: [32, 15.5], width: 2, depth: 2, top: 'level', maxThickness: 0.3, material: 'old red brick tree surround' });

  const polePoints = [-33, -13, 9, 33].map(z => [spine + 2.9, z]);
  const poleHeights = [];
  polePoints.forEach(p => {
    const h = api.environmentSample(p).height;
    poleHeights.push(h);
    api.place({ assetId: api.asset('pole'), position: [p[0], h, p[1]], role: 'environment' });
  });
  for (let i = 1; i < polePoints.length; i++) {
    api.placeBetween({
      assetId: api.asset('wire'),
      start: polePoints[i - 1], end: polePoints[i],
      dimensions: [0.12, 0.3, polePoints[i][1] - polePoints[i - 1][1]],
      spanAxis: 'z', elevation: Math.max(poleHeights[i - 1], poleHeights[i]) + 6.5,
      terrain: false
    });
  }

  const green = api.sampleProbabilityField({
    region: district, maxPoints: 10, candidates: 120, minDistance: 8, seed: api.seed + 17
  }, p => {
    const edge = Math.max(Math.abs(p[0]), Math.abs(p[1]));
    if (edge < 39 || edge > 43 || Math.abs(p[0] - spine) < 6) return 0;
    if ([-35, -11, 11, 35].some(z => Math.abs(p[1] - z) < 5)) return 0;
    if (occupied.some(b => Math.abs(p[0] - b[0]) < 7 && Math.abs(p[1] - b[1]) < 7)) return 0;
    const e = api.environmentSample(p);
    return 0.3 / (1 + Math.max(0, e.slope));
  });
  green.forEach((p, i) => {
    api.surface({ id: 'tree-soil-' + i, surface: 'soil', region: circle(p[0], p[1], 1), intensity: 0.8 });
    api.place({ assetId: api.asset('tree'), position: p, dimensions: [5, 6, 5], rotationY: i * 1.7, role: 'environment' });
  });
  api.spawn([spine, -43], 0);
}

function plan(api) {
  api.terrain("plain", { amplitude: 1.3, roughness: 0.16, seed: 2930301838 });

  const circle = (x, z, radius) => ({ kind: "circle", center: [x, z], radius });
  const polygon = points => ({ kind: "polygon", points });
  const candidates = [[0, -10], [-5, -11], [5, -10]];
  const measurements = candidates.map(p => {
    const points = [
      p,
      [p[0] - 13, p[1] - 21],
      [p[0] + 13, p[1] - 21],
      [p[0] - 13, p[1] + 21],
      [p[0] + 13, p[1] + 21]
    ];
    const samples = points.map(q => api.environmentSample(q));
    const heights = samples.map(s => s.height);
    return {
      p,
      height: samples[0].height,
      relief: Math.max.apply(null, heights) - Math.min.apply(null, heights),
      slope: Math.max.apply(null, samples.map(s => s.slope))
    };
  });
  measurements.sort((a, b) => a.relief - b.relief || a.slope - b.slope);
  const chosen = measurements[0];
  const cx = chosen.p[0];
  const cz = chosen.p[1];
  const level = chosen.height;
  const entranceZ = cz + 22;

  api.sculptTerrain({
    mode: "flatten",
    point: [cx, cz],
    radius: 28,
    strength: 1,
    targetHeight: level
  });
  api.sculptTerrain({
    mode: "flatten",
    point: [cx, entranceZ + 7],
    radius: 18,
    strength: 1,
    targetHeight: level
  });
  const base = api.environmentSample([cx, cz]);
  const entry = api.environmentSample([cx, entranceZ]);
  const south = api.environmentSample([cx, 43]);
  api.rampTerrain({
    start: [cx, entranceZ + 8],
    end: [cx, 43],
    width: 12,
    startHeight: entry.height,
    endHeight: south.height,
    softness: 0.8,
    strength: 1
  });
  api.environmentSample([cx, entranceZ + 12]);

  api.surface({
    id: "cathedral-precinct",
    surface: "paving",
    material: "weathered pale limestone flagstones",
    region: polygon([
      [cx - 19, cz - 25],
      [cx + 19, cz - 25],
      [cx + 19, entranceZ + 14],
      [cx - 19, entranceZ + 14]
    ])
  });
  api.surface({
    id: "forecourt-inlay",
    surface: "paving",
    material: "large pale limestone slabs with dark slate geometric borders",
    region: circle(cx, entranceZ + 9, 10)
  });

  api.requireAsset({
    key: "cathedral",
    name: "哥特大教堂",
    role: "structure",
    dimensions: [29, 43, 46],
    prompt: "One complete monumental medieval Gothic stone cathedral, standalone architectural object. Y+ up, Z+ front entrance, X+ right. Overall footprint includes every projecting buttress. Grand symmetrical west facade at Z+ with twin soaring square bell towers crowned by elaborate stone spires, a slightly taller slender crossing spire, a great deeply recessed stained glass rose window, three tall pointed arched entrance portals with carved archivolts and dark oak doors, the central door open into a shadowed vaulted interior. Tall cruciform nave, steep weathered dark slate roof, projecting transepts, polygonal apse at rear Z-, two tiers of elegant flying buttresses along both sides, slender pinnacles, crockets, tracery, gargoyles, carved saints and narrow jewel toned stained glass lancets. Pale warm gray limestone blocks with subtle age and darker recesses, refined realistic masonry, strongly vertical and imposing silhouette. Portals meet ground level, no external staircase. No surrounding terrain, other buildings, trees or plaza."
  });
  api.requireAsset({
    key: "statue",
    name: "石雕圣像",
    role: "environment",
    dimensions: [1.7, 4.8, 1.7],
    prompt: "One weathered Gothic limestone statue of a robed saint holding a closed book, standing on an ornate square stone pedestal, finely carved drapery and small pointed arch reliefs on pedestal. Standalone object, Y+ up, Z+ front, X+ right."
  });
  api.requireAsset({
    key: "bench",
    name: "石制长椅",
    role: "environment",
    dimensions: [3.4, 1.1, 0.9],
    prompt: "One elegant medieval pale limestone garden bench with a thick stone seat, low carved back and two solid sculpted supports, lightly weathered. Standalone object, Y+ up, Z+ front seating direction, X+ right."
  });
  api.requireAsset({
    key: "lamp",
    name: "铁艺灯柱",
    role: "environment",
    dimensions: [0.65, 3.6, 0.65],
    prompt: "One slender black wrought iron Gothic lantern post on a small stone foot, pointed lantern canopy, clear amber glass and restrained curled ironwork. Standalone object, Y+ up, Z+ front, X+ right."
  });
  api.requireAsset({
    key: "tree",
    name: "古老柏树",
    role: "environment",
    dimensions: [3.8, 12, 3.8],
    prompt: "One mature slender Italian cypress tree, tall tapering dark green evergreen crown and visible short textured trunk, natural irregular foliage, standalone tree without ground. Y+ up, Z+ front, X+ right."
  });

  const church = api.place({
    assetId: api.asset("cathedral"),
    position: [cx, base.height, cz],
    rotationY: 0,
    role: "structure"
  });
  api.foundation({
    under: [church],
    shape: "rounded-rectangle",
    width: 30,
    depth: 47,
    top: "level",
    maxThickness: 2,
    material: "large dressed limestone foundation blocks"
  });

  api.route({
    id: "processional-approach",
    points: [[cx, 44], [cx, 34], [cx, entranceZ + 8], [cx, entranceZ]],
    width: 9,
    curve: "polyline",
    surface: "paving",
    material: "light limestone slabs with dark slate edging"
  });
  api.route({
    id: "precinct-walk",
    points: [
      [cx, entranceZ + 8],
      [cx - 18, entranceZ + 8],
      [cx - 18, cz],
      [cx - 18, cz - 25],
      [cx + 18, cz - 25],
      [cx + 18, cz],
      [cx + 18, entranceZ + 8],
      [cx, entranceZ + 8]
    ],
    width: 3,
    curve: "polyline",
    surface: "paving",
    material: "worn limestone paving"
  });

  function ornament(key, x, z, yaw, support) {
    const ref = api.place({
      assetId: api.asset(key),
      position: [x, z],
      rotationY: yaw,
      role: "environment"
    });
    if (support) {
      api.foundation({
        under: [ref],
        width: 1.9,
        depth: 1.9,
        top: "level",
        maxThickness: 0.7,
        material: "limestone"
      });
    }
  }

  for (const side of [-1, 1]) {
    ornament("statue", cx + side * 11, entranceZ + 5, 0, true);
    ornament("statue", cx + side * 11, entranceZ + 16, 0, true);
    for (const z of [entranceZ + 4, entranceZ + 15, 36]) {
      ornament("lamp", cx + side * 6.4, z, 0, false);
    }
    for (const z of [cz - 12, cz + 2, entranceZ + 10]) {
      ornament("bench", cx + side * 21, z, -side * Math.PI / 2, false);
    }
  }

  const lawns = [
    polygon([[-45, -44], [cx - 22, -44], [cx - 22, 29], [-45, 38]]),
    polygon([[cx + 22, -44], [45, -44], [45, 38], [cx + 22, 29]])
  ];
  lawns.forEach((region, i) => {
    api.surface({ id: "garden-ground-" + i, surface: "grass", region });
    api.grass("cathedral-lawn-" + i, region, {
      preset: "meadow",
      density: 0.35,
      height: 0.16
    });
  });

  const trees = api.sampleProbabilityField({
    maxPoints: 24,
    candidates: 180,
    minDistance: 6,
    seed: 2930301838,
    bounds: { minX: -43, maxX: 43, minZ: -42, maxZ: 37 }
  }, p => {
    const x = p[0], z = p[1];
    if (Math.abs(x) > 43 || z < -42 || z > 37) return 0;
    if (Math.abs(x - cx) < 25) return 0;
    const sample = api.environmentSample(p);
    if (sample.slope > 0.5) return 0;
    return z < 16 ? 0.8 : 0.25;
  });
  trees.forEach(p => ornament("tree", p[0], p[1], Math.random() * Math.PI * 2, false));
  if (!trees.length) ornament("tree", -39, -30, 0, false);

  api.spawn([cx, 41], 180);
}

function plan(api) {
  api.terrain('mountains', { amplitude: 6, roughness: 0.62, seed: 1470973425 });
  api.modifyTerrain({
    modifier: 'mountain',
    region: { kind: 'circle', center: [0, 5], radius: 36 },
    amplitude: 10,
    softness: 0.38
  });
  api.modifyTerrain({
    modifier: 'ridge',
    region: { kind: 'path', points: [[-30, 18], [0, 8], [28, 26]], width: 15 },
    amplitude: 4,
    softness: 0.35
  });

  const candidates = [[0, 5], [-3, 7], [3, 8]];
  const observations = candidates.map(function (p) {
    return { p: p, s: api.environmentSample(p) };
  });
  let chosen = observations[0];
  for (let i = 1; i < observations.length; i++) {
    if (observations[i].s.slope < chosen.s.slope &&
        observations[i].s.height >= chosen.s.height - 2) chosen = observations[i];
  }
  const cx = chosen.p[0];
  const cz = chosen.p[1];
  const summit = Math.max(10, Math.min(15, chosen.s.height));
  function p(x, z) { return [cx + x, cz + z]; }
  function circle(x, z, r) {
    return { kind: 'circle', center: p(x, z), radius: r };
  }

  api.sculptTerrain({
    mode: 'flatten', point: p(0, 0), radius: 23,
    strength: 1, targetHeight: summit
  });
  api.sculptTerrain({
    mode: 'smooth', point: p(0, 0), radius: 25, strength: 0.22
  });
  const courtSample = api.environmentSample(p(0, 0));
  const floor = courtSample.height;
  api.surface({
    id: 'summit-rock', surface: 'rock',
    region: circle(0, 0, 32), intensity: 0.9
  });
  api.surface({
    id: 'castle-court', surface: 'paving', material: 'weathered grey limestone cobbles',
    region: { kind: 'polygon', points: [p(-15, -13), p(15, -13), p(15, 13), p(-15, 13)] },
    intensity: 1
  });

  const families = [
    ['keep', '主堡', 'One monumental medieval limestone keep, four storeys, thick weathered pale grey masonry, narrow arrow slits, tall arched entrance centered on the front, machicolations, crenellated parapets, two attached slender roof turrets with dark slate conical roofs, restrained crimson banners. No terrain or surrounding walls. Y+ up, Z+ front entrance, X+ right.', [12, 20, 10]],
    ['tower', '角楼', 'One standalone medieval cylindrical stone defensive tower, heavy battered masonry base, arrow slit windows, projecting machicolations and open crenellated fighting platform, weathered grey limestone, no ground. Y+ up, Z+ front entrance, X+ right.', [6, 13, 6]],
    ['wall', '城墙', 'One straight medieval limestone curtain wall module extending along local X, thick solid stone base, accessible parapet walk, crenellated battlements and corbels, weathered masonry. No towers or terrain. Y+ up, Z+ exterior front, X+ right.', [10, 8, 2]],
    ['gate', '城门', 'One medieval stone gatehouse with two integrated square battlement towers and a clear open central passage, raised iron portcullis, passage at ground level 4 meters wide and 5 meters high, weathered limestone, crimson pennants, no terrain. Y+ up, Z+ exterior front entrance, X+ right.', [11, 13, 6]],
    ['hall', '大厅', 'One standalone medieval castle great hall, grey stone walls, tall leaded Gothic windows, steep dark slate gabled roof, stone chimney and wooden arched door on the front. Y+ up, Z+ front entrance, X+ right.', [7, 10, 11]],
    ['well', '水井', 'One medieval courtyard well, circular limestone rim, dark open center, oak winding frame and rope bucket, small slate roof, no ground. Y+ up, Z+ front, X+ right.', [2.8, 4, 2.8]],
    ['banner', '旗杆', 'One tall medieval iron banner pole on a small stone foot, hanging long crimson cloth with a simple gold lion heraldic emblem, fabric billowing, no terrain. Y+ up, Z+ front, X+ right.', [1.7, 7, 1]],
    ['pine', '山松', 'One windswept mountain pine with irregular dark evergreen foliage and exposed twisted trunk, sparse asymmetric branches, no ground. Y+ up, Z+ front, X+ right.', [5, 8, 5]],
    ['rock', '峭岩', 'One jagged angular outcrop of weathered grey mountain rock, vertical fractures, small pale lichen patches, no ground plane. Y+ up, Z+ front, X+ right.', [6, 5, 5]]
  ];
  families.forEach(function (a) {
    api.requireAsset({ key: a[0], name: a[1], prompt: a[2], dimensions: a[3], role: a[0] === 'pine' || a[0] === 'rock' ? 'environment' : 'structure' });
  });

  function supported(key, x, z, yaw, w, d) {
    const pt = p(x, z);
    api.environmentSample(pt);
    api.sculptTerrain({ mode: 'flatten', point: pt, radius: Math.max(w, d) * 0.58, targetHeight: floor, strength: 1 });
    api.environmentSample(pt);
    const o = api.place({
      assetId: api.asset(key), position: [pt[0], floor, pt[1]],
      rotationY: yaw, role: 'structure'
    });
    api.foundation({
      under: [o], position: pt, width: w, depth: d,
      top: 'level', maxThickness: 7, material: 'rough grey limestone blocks'
    });
    return o;
  }

  supported('keep', 0, 6, Math.PI, 13, 11);
  supported('hall', -10, 0, Math.PI / 2, 8, 12);
  supported('gate', 0, -15, Math.PI, 12, 7);
  [[-16, -15], [16, -15], [-16, 15], [16, 15]].forEach(function (v) {
    supported('tower', v[0], v[1], Math.PI, 7, 7);
  });

  function wall(a, b) {
    const aa = p(a[0], a[1]);
    const bb = p(b[0], b[1]);
    const length = Math.hypot(bb[0] - aa[0], bb[1] - aa[1]);
    const o = api.placeBetween({
      assetId: api.asset('wall'), start: aa, end: bb,
      dimensions: [length, 8, 2], spanAxis: 'x', elevation: floor, terrain: false
    });
    api.foundation({ under: [o], top: 'level', maxThickness: 8, material: 'massive weathered limestone' });
  }
  wall([-16, -15], [-5.5, -15]);
  wall([5.5, -15], [16, -15]);
  wall([-16, -15], [-16, 15]);
  wall([16, -15], [16, 15]);
  wall([-16, 15], [16, 15]);

  supported('well', 7, -4, 0, 3.3, 3.3);
  supported('banner', -5, -10, Math.PI, 1.8, 1.8);
