    if (edge < 44 || (Math.abs(p[0]) < 7 && p[1] < -38)) return 0;
    var sample = api.environmentSample(p);
    return sample.slope < 0.7 ? 0.22 : 0.05;
  });
  scrub.forEach(function (p, i) {
    api.grass('desert-scrub-' + i, { kind: 'circle', center: p, radius: 0.65 },
      { preset: 'sand', density: 0.12, height: 0.22 });
  });
  api.spawn([0, -45], 0);
}
